import sqlite3,gzip,json,collections,time,hashlib
from pathlib import Path
B=Path(__import__('os').environ.get('F2_ROOT', str(Path(__file__).resolve().parents[1])));C=sqlite3.connect(B/'data/financial_actions.sqlite');C.execute('PRAGMA journal_mode=WAL');C.execute('PRAGMA synchronous=NORMAL');C.execute('PRAGMA temp_store=FILE');start=time.time()
C.executescript('''CREATE TABLE descriptive_rows(id INTEGER PRIMARY KEY,source_file TEXT,source_row INTEGER,transaction_key TEXT,award_key TEXT,award_id_explicit TEXT,title TEXT,description TEXT,evidence_excerpt TEXT,psc TEXT,naics TEXT,awarding_agency_code TEXT,awarding_sub_agency_code TEXT,funding_agency_code TEXT,funding_sub_agency_code TEXT,parent_award_id TEXT,solicitation_identifier TEXT,identifiers_json TEXT,money_json TEXT,raw_locator TEXT,source_url TEXT,retrieved_at TEXT);''')
files=sorted((B/'data/descriptive_sources').glob('*.jsonl.gz'))+[B/'data/normalized/usaspending_dod_research_grants.jsonl.gz']; audits={}; n=0;fields=collections.Counter();nonempty=collections.Counter(); idkeys=collections.Counter();batch=[]
for p in files:
 count=0
 with gzip.open(p,'rt') as f:
  for count,line in enumerate(f,1):
   r=json.loads(line);n+=1;fields.update(r.keys());nonempty.update(k for k,v in r.items() if v not in (None,'','[]','{}',[],{}));ids=json.loads(r.get('identifiers_json') or '{}');idkeys.update(k for k,v in ids.items() if v not in (None,''));
   batch.append((n,str(p.relative_to(B)),count,r.get('transaction_key',''),r.get('award_key',''),ids.get('award_id_piid') or ids.get('award_id_fain') or ids.get('award_id_uri') or '',r.get('title',''),r.get('text',''),r.get('evidence_excerpt',''),ids.get('product_or_service_code'),ids.get('naics_code'),ids.get('awarding_agency_code'),ids.get('awarding_sub_agency_code'),ids.get('funding_agency_code'),ids.get('funding_sub_agency_code'),ids.get('parent_award_id_piid'),ids.get('solicitation_identifier'),r.get('identifiers_json',''),r.get('money_json',''),r.get('raw_locator',''),r.get('source_url',''),r.get('retrieved_at','')))
   if len(batch)>=10000:
    C.executemany('INSERT INTO descriptive_rows VALUES('+','.join('?'*22)+')',batch);C.commit();batch=[]
    if n%100000==0:print(n,'description rows',round(time.time()-start,1),flush=True)
 if batch:C.executemany('INSERT INTO descriptive_rows VALUES('+','.join('?'*22)+')',batch);C.commit();batch=[]
 audits[p.name]={'rows':count,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'full_gzip_crc_read':'passed'}
C.executescript('''CREATE INDEX idx_description_tx ON descriptive_rows(transaction_key);CREATE INDEX idx_description_award ON descriptive_rows(award_key);CREATE INDEX idx_description_id ON descriptive_rows(award_id_explicit);
CREATE TABLE description_enrichment AS SELECT transaction_key,MIN(id) AS first_description_row,COUNT(*) AS source_count, GROUP_CONCAT(DISTINCT title || ' | ' || description || ' | ' || evidence_excerpt) AS description_text,GROUP_CONCAT(DISTINCT psc) AS psc_text,GROUP_CONCAT(DISTINCT naics) AS naics_text,GROUP_CONCAT(DISTINCT 'award_agency=' || COALESCE(awarding_agency_code,'') || ' awarding_sub_agency=' || COALESCE(awarding_sub_agency_code,'') || ' funding_agency=' || COALESCE(funding_agency_code,'') || ' funding_sub_agency=' || COALESCE(funding_sub_agency_code,'')) AS agency_text,GROUP_CONCAT(DISTINCT award_id_explicit) AS explicit_award_ids,COUNT(DISTINCT award_key) AS distinct_award_keys,COUNT(DISTINCT award_id_explicit) AS distinct_award_ids FROM descriptive_rows GROUP BY transaction_key; CREATE UNIQUE INDEX idx_enrichment_tx ON description_enrichment(transaction_key);
UPDATE source_rows SET description_text=COALESCE((SELECT description_text FROM description_enrichment d WHERE d.transaction_key=source_rows.transaction_key),''),psc_text=COALESCE((SELECT psc_text FROM description_enrichment d WHERE d.transaction_key=source_rows.transaction_key),''),naics_text=COALESCE((SELECT naics_text FROM description_enrichment d WHERE d.transaction_key=source_rows.transaction_key),''),agency_text=COALESCE((SELECT agency_text FROM description_enrichment d WHERE d.transaction_key=source_rows.transaction_key),'');
UPDATE source_rows SET award_id=(SELECT explicit_award_ids FROM description_enrichment d WHERE d.transaction_key=source_rows.transaction_key),award_id_parse_status='validated_against_explicit_source_identifier' WHERE transaction_key IN (SELECT transaction_key FROM description_enrichment WHERE distinct_award_ids=1);
CREATE VIEW transaction_details AS SELECT t.*,d.source_count AS description_source_count,d.first_description_row,r.award_id_explicit,r.awarding_agency_code,r.awarding_sub_agency_code,r.funding_agency_code,r.funding_sub_agency_code,r.parent_award_id,r.solicitation_identifier,r.money_json,r.title,r.description,r.evidence_excerpt,r.source_file AS description_source_file,r.source_row AS description_source_row FROM transactions t LEFT JOIN description_enrichment d USING(transaction_key) LEFT JOIN descriptive_rows r ON r.id=d.first_description_row;''');C.commit()
qs={'descriptive_physical_rows':'SELECT COUNT(*) FROM descriptive_rows','descriptive_unique_transaction_keys':'SELECT COUNT(*) FROM description_enrichment','descriptive_duplicate_rows':'SELECT SUM(source_count-1) FROM description_enrichment','financial_transactions_matched':'SELECT COUNT(*) FROM transactions t JOIN description_enrichment d USING(transaction_key)','financial_transactions_unmatched':'SELECT COUNT(*) FROM transactions t LEFT JOIN description_enrichment d USING(transaction_key) WHERE d.transaction_key IS NULL','descriptive_transactions_outside_financial':'SELECT COUNT(*) FROM description_enrichment d LEFT JOIN transactions t USING(transaction_key) WHERE t.transaction_key IS NULL','nonempty_description_transactions':"SELECT COUNT(*) FROM transactions WHERE LENGTH(TRIM(description_text,' |'))>0",'nonempty_psc_transactions':"SELECT COUNT(*) FROM transactions WHERE psc_text<>''",'nonempty_naics_transactions':"SELECT COUNT(*) FROM transactions WHERE naics_text<>''",'nonempty_agency_transactions':"SELECT COUNT(*) FROM transactions WHERE agency_text<>''",'explicit_identifier_validated_transactions':"SELECT COUNT(*) FROM transactions WHERE award_id_parse_status='validated_against_explicit_source_identifier'",'transaction_award_key_conflicts':'SELECT COUNT(*) FROM description_enrichment WHERE distinct_award_keys>1','transaction_explicit_award_id_conflicts':'SELECT COUNT(*) FROM description_enrichment WHERE distinct_award_ids>1'}
audit={'files':audits,'field_presence':dict(fields),'field_nonempty':dict(nonempty),'identifier_nonempty':dict(idkeys),'counts':{k:C.execute(q).fetchone()[0] for k,q in qs.items()},'elapsed_seconds':round(time.time()-start,1),'joins':'Exact transaction_key. All descriptions/title/evidence retained and concatenated uniquely per transaction, not joined on name. Explicit award_id_piid/fain validated by single consistent source identifier; all monetary aggregations still from financial action obligations, not money_json totals/ceilings.'}
(B/'lane1/enrichment_audit.json').write_text(json.dumps(audit,indent=2));print(json.dumps(audit,indent=2));C.execute('PRAGMA wal_checkpoint(TRUNCATE)');C.close()
